const body = $input.first().json.body || $input.first().json;

const contactId = body.contact_id || body.id || body.contactId || '';
const firstName = body.first_name || body.firstName || '';
const lastName = body.last_name || body.lastName || '';
const fullName = (firstName + ' ' + lastName).trim() || body.full_name || body.name || 'there';
const email = body.email || body.contact_email || '';
const tags = body.tags || [];

if (!email) {
  throw new Error('No email found for contact: ' + contactId);
}

if (tags.includes('outreach-sent')) {
  throw new Error('Already emailed: ' + email);
}

return [{ json: { contactId, fullName, email, tags } }];

const emailNode = $input.first().json;
const pickNode = $('Pick Mailbox').first().json;
return [{ json: { ...pickNode, sentFrom: pickNode.fromEmail } }];

